(function(){
 'use strict';
 const $=id=>document.getElementById(id),node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;};
 let target=null,picker=null,pickerReturn=null;
 const signature=()=>JSON.stringify(gameState.deck);
 const owned=id=>gameState.inventory.find(i=>i.instanceId===id);
 function returnToTeam(id){target=null;switchTab('deck');setLettersView('team');updateOwnedDeckContext();$('screen-deck').scrollTop=0;const focus=id?document.querySelector(`[data-deck-detail="${id}"]`):$('letters-tab-team');focus?.focus({preventScroll:true});}
 window.clearOwnedSearchFilters=()=>{for(const k of ['attr','ability'])if($('owned-filter-'+k))$('owned-filter-'+k).value='';if($('owned-filter-jis'))$('owned-filter-jis').value='all';const input=$('owned-character-search');if(input){input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));}filterCollection('all');};
 window.updateOwnedSearchStatus=count=>{const status=$('owned-search-status');if(!status)return;status.textContent=`${count} / ${gameState.inventory.length}体を表示`;$('btn-clear-owned-search').hidden=!$('owned-character-search').value.trim()&&gameState.currentFilter==='all'&&!$('owned-filter-attr')?.value&&!$('owned-filter-ability')?.value;};
 window.updateOwnedDeckContext=()=>{const box=$('owned-deck-context');if(!box)return;box.hidden=!target;if(!target)return;const item=owned(gameState.deck[target.index]);$('owned-deck-context-title').textContent=item?`編成${target.index+1}「${item.char}」の入れ替え`:'空き枠に文字を編成';$('owned-deck-context-note').textContent='下の文字の「ここに編成」を押すと確定します。詳細を見るだけでは編成は変わりません。';};
 window.beginOwnedDeckChoice=index=>{if(!Number.isInteger(index)||index<0||index>2)return;target=null;openPracticeDeck('deployment',index);};
 window.cancelOwnedDeckChoice=()=>returnToTeam();
 function rejectChoice(){target=null;closeOwnedDeckPicker();returnToTeam();showToast('編成や所持文字が変わりました。文字を選び直してください。');}
 function commitChoice(id,selection){const item=owned(id);if(!item||selection.signature!==signature()||gameState.deck.includes(id)){rejectChoice();return;}const index=selection.index;if(index<0||index>gameState.deck.length||index>2){rejectChoice();return;}const previous=owned(gameState.deck[index]);gameState.deck[index]=id;saveState();closeOwnedDeckPicker(false);renderDeckSlots();renderCollection();updateBattleDeckSummary();returnToTeam(id);$('deck-recommendation-status').textContent=previous?`編成${index+1}：${previous.char} → ${item.char}に入れ替えました。`:`編成${index+1}に「${item.char}」を追加しました。`;}
 window.chooseOwnedCharacterForDeck=id=>{
  const item=owned(id);if(!item||gameState.deck.includes(id))return;
  if(target){commitChoice(id,target);return;}
  if(gameState.deck.length<3){commitChoice(id,{index:gameState.deck.length,signature:signature()});return;}
  picker={id,signature:signature()};pickerReturn=document.activeElement;pausePlayerOverlay();const stats=getKanjiStats(item);$('deck-replace-title').textContent=`「${item.char}」をどこに編成しますか？`;$('deck-replace-candidate').textContent=`Lv.${item.level}・${ATTR_INFO[item.attr].name}属性・威力 ${stats.power}・重量 ${stats.weight}`;const box=$('deck-replace-options');box.replaceChildren();gameState.deck.forEach((current,index)=>{const piece=owned(current),b=node('button','deck-replace-option');b.type='button';b.dataset.deckReplaceChoice=String(index);const number=node('span','',`編成${index+1}`),glyph=node('strong','kanji-font',piece.char),level=node('span','',`Lv.${piece.level}`),action=node('small','','この文字と入れ替え');b.append(number,glyph,level,action);b.onclick=()=>{if(picker)commitChoice(picker.id,{index,signature:picker.signature});};box.append(b);});$('modal-deck-replace').classList.remove('hidden');$('btn-deck-replace-cancel').focus();
 };
 window.closeOwnedDeckPicker=(restore=true)=>{picker=null;$('modal-deck-replace').classList.add('hidden');resumePlayerEngine();if(restore&&pickerReturn?.isConnected)pickerReturn.focus();};
 window.decorateOwnedCharacterCard=(card,item,inDeck)=>{
  const tools=node('details','owned-item-tools');tools.append(node('summary','','ルビ解放・ロック'));tools.append(...[...card.children].filter(n=>n.matches('.ruby-unlock-action,.item-lock')));
  const button=node('button','inventory-action owned-deck-action',inDeck?'編成中':target?'ここに編成':'編成する');button.type='button';button.disabled=inDeck;button.dataset.ownedDeckItem=item.instanceId;button.setAttribute('aria-label',inDeck?`${item.char}は編成中`:`${item.char}を${target?'選んだ枠に':''}編成`);button.onclick=()=>chooseOwnedCharacterForDeck(item.instanceId);card.append(button,tools);
 };
 window.decorateDeckSlots=()=>{for(const slot of $('deck-slots-container').children){if(!slot.classList.contains('deck-slot-card'))continue;const index=Number(slot.dataset.deckSlot),button=node('button','deck-replace-action','入れ替え');button.type='button';button.dataset.deckReplaceSlot=String(index);button.setAttribute('aria-label',`編成${index+1}の文字を入れ替える`);button.onclick=()=>beginOwnedDeckChoice(index);slot.insertBefore(button,slot.querySelector('.deck-remove'));}updateOwnedDeckContext();};
 const originalSwitch=window.switchTab;window.switchTab=tab=>{if(tab!=='deck')target=null;originalSwitch(tab);updateOwnedDeckContext();};
 document.addEventListener('keydown',e=>{if($('modal-deck-replace').classList.contains('hidden'))return;if(e.key==='Escape'){e.preventDefault();closeOwnedDeckPicker();}else if(e.key==='Tab'){const buttons=[...$('modal-deck-replace').querySelectorAll('button')],first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 window.addEventListener('load',()=>{const panel=document.querySelector('.owned-characters-panel'),context=node('div','owned-deck-context');context.id='owned-deck-context';context.hidden=true;const title=node('h3');title.id='owned-deck-context-title';const note=node('p');note.id='owned-deck-context-note';const cancel=node('button','quiet-action','編成へ戻る');cancel.onclick=cancelOwnedDeckChoice;context.append(title,note,cancel);panel.insertBefore(context,$('owned-character-search').parentElement);const row=node('div','owned-search-feedback'),status=node('p');status.id='owned-search-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');const clear=node('button','quiet-action','検索・絞り込みをクリア');clear.id='btn-clear-owned-search';clear.onclick=clearOwnedSearchFilters;row.append(status,clear);$('owned-character-search').parentElement.append(row);$('btn-choose-owned').textContent='編成を変更';$('btn-choose-owned').onclick=()=>beginOwnedDeckChoice(0);renderDeckSlots();renderCollection();});

window.addEventListener('load',()=>{const panel=document.querySelector('.owned-characters-panel'),filters=node('div','practice-picker-filters');const add=(key,label,options)=>{const l=node('label','',label),select=node('select');select.id='owned-filter-'+key;for(const [value,text]of options){const o=node('option','',text);o.value=value;select.append(o);}select.onchange=()=>key==='jis'?filterCollection(select.value):renderCollection();l.append(select);filters.append(l);};add('jis','水準・種類',[['all','すべて'],['1','JIS第1水準'],['2','JIS第2水準'],['3','JIS第3水準'],['4','JIS第4水準'],['element','元素文字'],['fish','魚偏の文字'],['special','特殊文字'],['secret','シークレット']]);add('attr','属性',[['','すべて'],['wood','木'],['fire','火'],['earth','土'],['metal','金'],['water','水']]);add('ability','装備ルビの能力',[['','すべて'],...Object.values(KanjiReadAbilities.abilities).map(a=>[a.id,a.name])]);const sort=$('collection-sort'),sortParent=sort.parentElement,label=node('label','','並び順');label.append(sort);filters.append(label);sortParent.remove();for(const id of ['all','1','2','3','4','element','fish','special','secret'])$('filter-'+id).hidden=true;const legacyFilters=$('owned-filters');if(legacyFilters){legacyFilters.hidden=true;legacyFilters.style.display="none";}panel.querySelector('h3').parentElement.after(filters);const base=window.ownedCharacterMatches;window.ownedCharacterMatches=item=>(!base||base(item))&&(!$('owned-filter-attr').value||item.attr===$('owned-filter-attr').value)&&(!$('owned-filter-ability').value||getReadingAbilities(item).some(a=>a.id===$('owned-filter-ability').value));window.filterOwnedCharacters=items=>items.filter(window.ownedCharacterMatches);const oldFilter=window.filterCollection;window.filterCollection=value=>{const select=$('owned-filter-jis');if(select)select.value=value;return oldFilter(value);};renderCollection();});

})();
